    "scanIgnoringComments": true,
    "matchLines": [
      {
        "match": "/process\\.env\\.(GITHUB_TOKEN|GH_TOKEN|FLEET_GITHUB_TOKEN)/",
        "what": "reads a GitHub REST token from the environment — in-session migration code has no REST credential"
      },
      {
        "match": "/\\bmakeGh\\s*\\(|from\\s+['\"][^'\"]*\\bfleet-api/",
        "what": "uses the REST client (makeGh / fleet-api) — in-session migration code has no REST credential"
      },
      {
        "match": "/['\"`]https?:\\/\\/api\\.github\\.com/",
        "what": "targets the GitHub REST API (api.github.com) directly — in-session migration code has no REST credential"
      }
    ]
  }
]

